function normalizeLang(raw){
  const l=(raw||'').toLowerCase();
  if(l.startsWith('nl'))return 'nl'; if(l.startsWith('de'))return 'de'; if(l.startsWith('fr'))return 'fr'; if(l.startsWith('es'))return 'es'; if(l.startsWith('pt'))return 'pt'; return 'en';
}
function currentPageKey(){
  const p=(location.pathname.split('/').pop()||'index.html').replace('.html','');
  return p==='index'?'home':p;
}
function applyLang(lang){
  lang=MP_LANGS.includes(lang)?lang:'en'; localStorage.setItem('mpLang',lang); document.documentElement.lang=lang;
  const dict=translations[lang];
  document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(dict[k]!==undefined)el.textContent=dict[k]});
  const page=currentPageKey(); if(dict['meta.'+page])document.title=dict['meta.'+page];
  const sel=document.getElementById('langSelect'); if(sel)sel.value=lang;
}
document.addEventListener('DOMContentLoaded',()=>{
  const saved=localStorage.getItem('mpLang'); const lang=saved||normalizeLang(navigator.language||navigator.userLanguage);
  applyLang(lang);
  const sel=document.getElementById('langSelect'); if(sel)sel.addEventListener('change',e=>applyLang(e.target.value));
});
